    title: "交点計算と座標法求積（記述式の核心）",
    body: `
<p>記述式（土地）で毎年のように出るのが「分筆線と筆界線の<b>交点計算</b>」→「<b>座標法による求積</b>」→「地積測量図」の流れ。この講義で原理から本試験の答案処理までを一気通貫で身につける。</p>

<h4>1. 交点計算 — 4つの出題パターン</h4>
<table class="simple">
<tr><th>パターン</th><th>与えられ方</th><th>処理</th></tr>
<tr><td>①2点・2点</td><td>直線AB と 直線CD</td><td>各直線の方向角を逆計算で出して③へ</td></tr>
<tr><td>②点＋方向角</td><td>A・Tα と B・Tβ</td><td>交点公式（下記）へ直行</td></tr>
<tr><td>③平行線</td><td>「ABに平行で点Cを通る直線」</td><td>方向角を流用して②へ</td></tr>
<tr><td>④垂線</td><td>「ABに垂直」</td><td>方向角±90°して②へ</td></tr>
</table>
<p><b>交点公式</b>: 点Aから方向角Tαの直線と、点Bから方向角Tβの直線の交点Pは、まずAからPまでの距離aを求める。</p>
<p style="text-align:center"><b>a＝{(Yb−Ya)cosTβ−(Xb−Xa)sinTβ}÷sin(Tα−Tβ)</b></p>
<p>次に放射計算: P＝(Xa＋a·cosTα, Ya＋a·sinTα)。</p>
<div class="ex">A(120,100)・Tα=90°、B(95,116)から方向角158°7′48″の直線（K→L方向）。分母 sin(90°−158°7′48″)、分子に座標差を代入して a を求め、AからTα方向にa進める——という流れを、L01の複素数モードで処理する。記述タブのW01が実戦例。</div>
<div class="trap">求めた交点Pは<b>必ずもう一方の直線で検算</b>する（BからPへの方向角がTβに一致するか）。交点のミスは求積・作図・申請書まで連鎖して20点近く失う。「検算1分で20点の保険」。</div>

<h4>2. 座標法による面積計算（倍面積法）</h4>
<p>閉じた多角形の頂点を一周する順に並べ、次式で計算する。</p>
<p style="text-align:center"><b>倍面積＝Σ Xᵢ（Yᵢ₊₁−Yᵢ₋₁）</b>　→　面積＝|倍面積|÷2</p>
<div class="why">各頂点と隣接2点で作る台形の面積を足し引きしている（台形公式の整理形）。頂点を時計回りに並べると正、反時計回りだと負になる——符号は気にせず絶対値を取ればよいが、<b>並び順が一周になっていないと完全に狂う</b>。図を描いてから式を立てる。</div>
<div class="ex">A(120,100)→P(120,106)→Q(100,114)→D(100,104)の順で一周:<br>
A: 120×(106−104)=240<br>P: 120×(114−100)=1680<br>Q: 100×(104−106)=−200<br>D: 100×(100−114)=−1400<br>合計320 ⟹ 面積160.00㎡。<b>本試験の求積表もこの形式で書かせる</b>。</div>

<h4>3. 地積の端数処理（規則100条）— 3秒で正答できる頻出知識</h4>
<table class="simple">
<tr><th>計算面積</th><th>地積</th><th>処理</th></tr>
<tr><td>123.456㎡</td><td><b>123㎡</b></td><td>10㎡超 → 1㎡未満切捨て</td></tr>
<tr><td>9.876㎡</td><td><b>9.87㎡</b></td><td>10㎡以下 → 0.01㎡未満切捨て</td></tr>
<tr><td>10.00㎡ちょうど</td><td><b>10.00㎡</b></td><td>「10㎡以下」に含まれる（小数2位まで）</td></tr>
</table>
<div class="trap">四捨五入ではなく<b>切捨て</b>。また、地積測量図の「求積表」には計算値（小数2位等）を書き、「地積」欄には端数処理後の値を書く——2つの欄で書く数字が違うのが正しい。</div>

<h4>4. 辺長計算と分筆計算</h4>
<ul>
<li><b>辺長</b>: 各筆界点間の距離（逆計算）。地積測量図に記入必須。全辺を出したら<b>図形が閉じるか</b>（座標に戻るか）も確認。</li>
<li><b>面積指定分筆</b>: 「分筆後の甲地を◯㎡とせよ」型。分筆線の位置を未知数にして面積の式を立て、逆算する。三角形の面積＝½·底辺·高さ、台形＝½(上底+下底)×高さの初等公式も併用する。</li>
</ul>
<div class="pt">交点計算→求積→端数処理の3点セットは<b>計算道場タブで毎日2問</b>。本試験では「計算条件（公差内か・座標の与えられ方）」を問題文の隅に書く癖があるので、計算前に問題文を二度読みする習慣を。</div>`,
